/* TREKSTONE homepage · page scripts, in order, loaded with defer */

try {
/* Faster first load · section photos (CSS backgrounds) load when their section is within 1.5 screens. */
(() => {
  'use strict';
  const secs = [...document.querySelectorAll('[data-lazy-bg]')];
  const show = (el) => el.classList.add('is-near');
  if (!('IntersectionObserver' in window)) { secs.forEach(show); return; }
  const io = new IntersectionObserver((es) => es.forEach((e) => { if (e.isIntersecting) { show(e.target); io.unobserve(e.target); } }),
    { rootMargin: '150% 0px' });
  secs.forEach((el) => io.observe(el));
  addEventListener('beforeprint', () => secs.forEach(show));
})();
} catch (e) { setTimeout(() => { throw e; }); }

try {
/* Header state, mobile menu and the "Discuss a lot" dialog.
   The form writes the request as an email in the visitor's own mail app, addressed to TREKSTONE.
   Nothing is sent from or stored by the website; the visitor sends the email themselves. */
(() => {
  'use strict';
  const $ = (s, p=document) => p.querySelector(s);
  const $$ = (s, p=document) => Array.from(p.querySelectorAll(s));
  const header = $('#siteHeader');
  const mobileToggle = $('[data-mobile-toggle]'), mobileMenu = $('[data-mobile-menu]');
  function closeMobile() {
    if(mobileMenu) mobileMenu.hidden=true;
    mobileToggle?.setAttribute('aria-expanded','false');mobileToggle?.setAttribute('aria-label','Open menu');
  }
  mobileToggle?.addEventListener('click',()=>{
    const open=mobileMenu.hidden; mobileMenu.hidden=!open;
    mobileToggle.setAttribute('aria-expanded',String(open));mobileToggle.setAttribute('aria-label',open?'Close menu':'Open menu');
  });
  $$('[data-mobile-menu] a').forEach(a=>a.addEventListener('click',closeMobile));
  document.addEventListener('keydown',event=>{
    if(event.key!=='Escape')return;
    if(mobileMenu&&!mobileMenu.hidden){closeMobile();mobileToggle.focus();}
  });
  matchMedia('(min-width:1061px)').addEventListener('change',e=>{if(e.matches)closeMobile();});
  let scrollScheduled=false;
  const sections=$$('main section[id]');
  const navLinks=$$('.desktop-nav a[href^="#"]');
  function updateHeader(){
    header?.classList.toggle('scrolled',scrollY>12);
    const active=sections.filter(s=>s.getBoundingClientRect().top<160).at(-1)?.id;
    navLinks.forEach(a=>{if(a.hash==='#'+active)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');});
    scrollScheduled=false;
  }
  addEventListener('scroll',()=>{if(!scrollScheduled){scrollScheduled=true;requestAnimationFrame(updateHeader);}},{passive:true});updateHeader();

  // One native dialog, proper focus restoration, no false submission confirmation.
  const modal=$('[data-modal]'), modalTitle=$('[data-modal-title]'), modalText=$('[data-modal-text]');
  const form=$('[data-contact-form]'), success=$('[data-modal-success]'), modalCta=$('[data-modal-cta]');
  let lastFocused=null;
  function openModal(title,text,{contact=false,cta=true}={}){
    if(!modal)return;
    lastFocused=document.activeElement;closeMobile();
    modalTitle.textContent=title;modalText.textContent=text;form.hidden=!contact;success.hidden=true;modalCta.hidden=contact||!cta;
    if(!modal.open)modal.showModal();
    document.body.style.paddingRight=Math.max(0,innerWidth-document.documentElement.clientWidth)+'px';document.body.style.overflow='hidden';
  }
  modal?.addEventListener('close',()=>{document.body.style.overflow='';document.body.style.paddingRight='';lastFocused?.focus({preventScroll:true});});
  $('[data-modal-close]')?.addEventListener('click',()=>modal.close());
  modal?.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
  function contact(){openModal('Discuss a lot','Tell us what you have and where it is. We will come back with a grading and routing plan.',{contact:true});}
  $$('[data-open-contact]').forEach(b=>b.addEventListener('click',contact));modalCta?.addEventListener('click',contact);
  if(location.hash==='#discuss')setTimeout(contact);   // "Discuss a lot" on the legal pages lands here
  form?.addEventListener('submit',event=>{
    event.preventDefault();if(!form.reportValidity())return;
    const data=new FormData(form), val=k=>String(data.get(k)||'').trim();
    const rows=[['Name',val('name')],['Company',val('company')],['Email',val('email')],['Phone',val('phone')],['Inventory',val('inventory')],
      ['Approximate units',val('units')],['Where it is now',val('location')]]
      .filter(r=>r[1]).map(r=>r[0]+': '+r[1]).join('\r\n');
    const subject='Lot enquiry from '+val('name')+(val('company')?', '+val('company'):'');
    const link=msg=>'mailto:soureno@trekstone.net?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent((msg.length?msg.join('')+'\r\n\r\n':'')+rows);
    // Some systems ignore mail links over about 2,000 characters, so a very long message is shortened to fit.
    let msg=[...val('message')], url=link(msg);
    if(url.length>1900){let lo=0,hi=msg.length;while(lo<hi){const mid=(lo+hi+1)>>1;if(link([...msg.slice(0,mid),' […]']).length<=1900)lo=mid;else hi=mid-1;}url=link([...msg.slice(0,lo),' […]']);}
    location.href=url;
    success.hidden=false;success.scrollIntoView({block:'nearest'});
  });
})();
} catch (e) { setTimeout(() => { throw e; }); }

try {
/* Portal preview: two views of one sample lot. The figures count up and the outcome bar fills once,
   when the preview scrolls into view. Sample data only; nothing is loaded from anywhere. */
(() => {
  'use strict';
  const root = document.querySelector('[data-portal]'); if (!root) return;
  const tabs = [...root.querySelectorAll('[data-portal-tab]')], panels = [...root.querySelectorAll('[data-portal-panel]')];
  function show(key, focus) {
    tabs.forEach(t => { const on = t.dataset.portalTab === key; t.setAttribute('aria-selected', String(on)); t.tabIndex = on ? 0 : -1; if (on && focus) t.focus(); });
    panels.forEach(p => { p.hidden = p.dataset.portalPanel !== key; });
  }
  tabs.forEach((t, i) => {
    t.addEventListener('click', () => show(t.dataset.portalTab));
    t.addEventListener('keydown', e => {
      const m = { ArrowRight: 1, ArrowLeft: -1 }[e.key]; if (!m) return;
      e.preventDefault(); show(tabs[(i + m + tabs.length) % tabs.length].dataset.portalTab, true);
    });
  });
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const nums = [...root.querySelectorAll('[data-portal-count]')];
  const run = () => {
    root.classList.add('is-live'); if (reduce) return;
    nums.forEach(el => {
      const to = +el.dataset.portalCount, t0 = performance.now(), dur = 1200;
      const tick = now => { const k = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - k, 3); el.textContent = Math.round(to * e).toLocaleString('en-US'); if (k < 1) requestAnimationFrame(tick); };
      requestAnimationFrame(tick);
    });
  };
  if (!reduce && 'IntersectionObserver' in window) { const io = new IntersectionObserver(es => { if (es[0].isIntersecting) { io.disconnect(); run(); } }, { threshold: .35 }); io.observe(root); }
  else run();
  addEventListener('beforeprint', () => root.classList.add('is-live'));
})();
} catch (e) { setTimeout(() => { throw e; }); }

try {
/* Announcement bar, scroll reveals, count-ups and the header offset for anchor jumps. */
(() => {
  'use strict';
  const $ = (s, p = document) => p.querySelector(s), $$ = (s, p = document) => [...p.querySelectorAll(s)];
  const root = document.documentElement, reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const header = $('#siteHeader');

  // Announcement bar
  $('[data-announce-close]')?.addEventListener('click', () => { $('[data-announce]')?.remove(); root.classList.add('no-announce'); });

  // Keep the header solid whenever the menu is open (works where :has() is unsupported too)
  const syncMenu = () => header?.classList.toggle('menu-open', $$('[data-mobile-menu]').some(p => !p.hidden));
  if (header && 'MutationObserver' in window) new MutationObserver(syncMenu).observe(header, { subtree: true, attributes: true, attributeFilter: ['hidden'] });

  // Scroll reveals
  const rv = $$('.rv');
  if (!reduce && 'IntersectionObserver' in window) {
    const io = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { e.target.classList.add('is-in'); io.unobserve(e.target); } }), { rootMargin: '0px 0px -6% 0px' });
    rv.forEach(el => io.observe(el));
  } else rv.forEach(el => el.classList.add('is-in'));

  // Count-ups
  const counters = $$('[data-count]');
  const run = el => {
    const to = +el.dataset.count, suf = el.dataset.suffix || '', t0 = performance.now(), dur = 1400;
    const tick = now => { const k = Math.min(1, (now - t0) / dur), e = 1 - Math.pow(1 - k, 3); el.textContent = Math.round(to * e).toLocaleString('en-US') + suf; if (k < 1) requestAnimationFrame(tick); };
    requestAnimationFrame(tick);
  };
  if (!reduce && 'IntersectionObserver' in window) {
    const io2 = new IntersectionObserver(es => es.forEach(e => { if (e.isIntersecting) { run(e.target); io2.unobserve(e.target); } }), { threshold: .6 });
    counters.forEach(el => io2.observe(el));
  }

  // Header offset for anchor jumps
  const setPad = () => { root.style.setProperty('--x-head-solid', (header?.querySelector('.x-bar')?.offsetHeight || 72) + 'px'); root.style.setProperty('--x-head-h', (header?.offsetHeight || 112) + 'px'); };
  setPad(); addEventListener('resize', setPad, { passive: true });
  $('[data-mobile-toggle]')?.addEventListener('click', () => requestAnimationFrame(setPad));
  $('[data-announce-close]')?.addEventListener('click', () => requestAnimationFrame(setPad));
})();
} catch (e) { setTimeout(() => { throw e; }); }

try {
/* Gentle scroll parallax for the Earth behind "Why now". */
(() => {
  'use strict';
  const s = document.querySelector('.x-now'); if (!s || matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  let raf = 0, on = false;
  const update = () => { raf = 0; const r = s.getBoundingClientRect(), c = r.top + r.height / 2 - innerHeight / 2; s.style.setProperty('--x-par', (-c * 0.1).toFixed(1) + 'px'); };
  addEventListener('scroll', () => { if (on && !raf) raf = requestAnimationFrame(update); }, { passive: true });
  if ('IntersectionObserver' in window) new IntersectionObserver(e => { on = e[0].isIntersecting; if (on) update(); }, { rootMargin: '100px' }).observe(s);
})();
} catch (e) { setTimeout(() => { throw e; }); }

try {
/* "One lot, 90 days" card carousel. */
(() => {
  'use strict';
  const root = document.querySelector('[data-trust]'); if (!root) return;
  const row = root.querySelector('[data-trust-row]'), cards = [...root.querySelectorAll('[data-trust-card]')], bar = root.querySelector('[data-trust-bar]');
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches, stacked = () => matchMedia('(max-width: 720px)').matches;
  let cur = 0, timer = 0, touched = false, visible = false;
  function place() {
    row.style.transform = ''; return;   // V45: every card fits the width; the active one simply widens
    const other = cards.find((c, i) => i !== cur), gap = parseFloat(getComputedStyle(row).columnGap || getComputedStyle(row).gap) || 14;
    const w = other ? parseFloat(getComputedStyle(other).flexBasis) || other.getBoundingClientRect().width : 0;
    row.style.transform = `translateX(${-(cur * (w + gap))}px)`;
  }
  function set(i, user) {
    cur = (i + cards.length) % cards.length;
    cards.forEach((c, k) => { c.classList.toggle('is-active', k === cur); c.setAttribute('aria-pressed', String(k === cur)); });
    if (bar) bar.style.transform = `translateX(${cur * 100}%)`;
    place();
    if (user) { touched = true; clearInterval(timer); timer = 0; }
  }
  const play = () => { if (reduce || touched || timer || !visible || stacked()) return; timer = setInterval(() => set(cur + 1, false), 6000); };
  cards.forEach((c, k) => c.addEventListener('click', () => set(k, true)));
  root.querySelector('[data-trust-prev]')?.addEventListener('click', () => set(cur - 1, true));
  root.querySelector('[data-trust-next]')?.addEventListener('click', () => set(cur + 1, true));
  if (bar) bar.style.width = (100 / cards.length) + '%';
  addEventListener('resize', place, { passive: true });
  if ('IntersectionObserver' in window) new IntersectionObserver(es => { visible = es[0].isIntersecting; if (visible) play(); else { clearInterval(timer); timer = 0; } }, { threshold: 0.3 }).observe(root);
  set(0, false);
})();
} catch (e) { setTimeout(() => { throw e; }); }

try {
/* Network section: photo tiles reuse images already on the page where they can (no double download).
   The tiles get their photos only when the section is within 1.5 screens, so they don't load with the top of the page. */
(() => {
  'use strict';
  const tiles = [...document.querySelectorAll('.x-omni__ph[data-img]')]; if (!tiles.length) return;
  let done = false;
  const paint = () => {
    if (done) return; done = true;
    tiles.forEach(el => {
      const k = el.dataset.img;
      if (el.dataset.bg) { el.style.backgroundImage = `url("${el.dataset.bg}")`; return; }
      const img = document.querySelector(`img[data-asset="${k}"]`);
      if (img && img.currentSrc || img && img.src) el.style.backgroundImage = `url("${img.currentSrc || img.src}")`;
    });
  };
  addEventListener('beforeprint', paint);
  if (!('IntersectionObserver' in window)) { paint(); return; }
  const io = new IntersectionObserver(es => { if (es.some(e => e.isIntersecting)) { io.disconnect(); paint(); } }, { rootMargin: '150% 0px' });
  tiles.forEach(el => io.observe(el));
})();
} catch (e) { setTimeout(() => { throw e; }); }

try {
/* The strand ribbon draws itself along the forest road when the section comes into view. */
(() => {
  'use strict';
  const s = document.querySelector('[data-forest]'); if (!s) return;
  if (!('IntersectionObserver' in window) || matchMedia('(prefers-reduced-motion: reduce)').matches) { s.classList.add('is-drawn'); return; }
  const io = new IntersectionObserver(es => { if (es[0].isIntersecting) { s.classList.add('is-drawn'); io.disconnect(); } }, { threshold: 0.22 });
  io.observe(s);
})();
} catch (e) { setTimeout(() => { throw e; }); }

